"""Shared helpers for the cross-region failover workspace.

These helpers implement the common data semantics described in the
workspace README: payload loading, evidence-field normalization,
revision resolution, and component-record merging.
"""
import json
from pathlib import Path


CATEGORIES = ('prepare', 'copy', 'verify')
CATEGORY_RANK = {'prepare': 0, 'copy': 1, 'verify': 2}


def ceil_div(a, b):
    return -(-a // b)


def load_payload(path):
    """Read a UTF-8 JSON file; a top-level object or array is legal."""
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError('payload is not valid JSON') from exc
    if not isinstance(data, (dict, list)):
        raise ValueError('payload top-level must be an object or array')
    return data


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _require_string(value, field):
    if not isinstance(value, str):
        raise ValueError('%s must be a string' % field)
    return value


def normalize_id(value):
    s = _require_string(value, 'id').strip()
    if not s:
        raise ValueError('id must be non-empty')
    return s


def normalize_text(value, field):
    s = _require_string(value, field).strip()
    if not s:
        raise ValueError('%s must be non-empty' % field)
    return s.lower()


def normalize_category(value):
    c = normalize_text(value, 'category')
    if c not in CATEGORIES:
        raise ValueError('category must be prepare/copy/verify')
    return c


def normalize_tags(value):
    if not isinstance(value, list):
        raise ValueError('tags must be a list')
    out = []
    for tag in value:
        s = _require_string(tag, 'tag').strip()
        if not s:
            raise ValueError('tags must contain only non-empty strings')
        out.append(s.lower())
    return sorted(set(out))


def normalize_int(value, field, minimum):
    if not _is_int(value):
        raise ValueError('%s must be an integer' % field)
    if value < minimum:
        raise ValueError('%s must be >= %d' % (field, minimum))
    return value


def normalize_bool(value, field):
    if not isinstance(value, bool):
        raise ValueError('%s must be a boolean' % field)
    return value


def parse_evidence_record(raw):
    if not isinstance(raw, dict):
        raise ValueError('evidence record must be an object')
    rid = normalize_id(raw.get('id'))
    revision = normalize_int(raw.get('revision'), 'revision', 0)
    owner = normalize_text(raw.get('owner'), 'owner')
    category = normalize_category(raw.get('category'))
    tags = normalize_tags(raw.get('tags'))
    failures = normalize_int(raw.get('failures'), 'failures', 0)
    total = normalize_int(raw.get('total'), 'total', 1)
    lag = normalize_int(raw.get('lag'), 'lag', 0)
    valid = normalize_bool(raw.get('valid'), 'valid')
    if failures > total:
        raise ValueError('failures must not exceed total')
    return {
        'id': rid,
        'revision': revision,
        'owner': owner,
        'category': category,
        'tags': tags,
        'failures': failures,
        'total': total,
        'lag': lag,
        'valid': valid,
    }


def resolve_evidence(payload):
    """Validate all evidence records, resolve revision conflicts, dedup,
    and keep the newest revision per id."""
    if not isinstance(payload, list):
        raise ValueError('evidence payload must be an array')
    records = [parse_evidence_record(r) for r in payload]
    seen = {}
    for rec in records:
        key = (rec['id'], rec['revision'])
        if key in seen and seen[key] != rec:
            raise ValueError(
                'conflicting revisions for id %r revision %r' % (rec['id'], rec['revision'])
            )
        seen[key] = rec
    latest = {}
    for rec in records:
        if rec['id'] not in latest or rec['revision'] > latest[rec['id']]['revision']:
            latest[rec['id']] = rec
    return list(latest.values())


def evidence_transform(payloads, contract, score_fn):
    records = resolve_evidence(payloads[0])
    source = contract['name']
    out = []
    for rec in records:
        score = max(0, min(20, score_fn(rec, contract)))
        out.append({
            'id': rec['id'],
            'source': source,
            'owner': rec['owner'],
            'tags': rec['tags'],
            'category': rec['category'],
            'score': score,
        })
    out.sort(key=lambda r: (r['source'], r['id']))
    return {
        'name': source,
        'result': {
            'records': out,
            'count': len(out),
            'score_total': sum(r['score'] for r in out),
        },
    }


def unwrap_component(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    raise ValueError('input must be a component encapsulation')


def merge_component_records(payloads):
    merged = {}
    for payload in payloads:
        result = unwrap_component(payload)
        if not isinstance(result, dict):
            raise ValueError('component result must be an object')
        records = result.get('records')
        if not isinstance(records, list):
            raise ValueError('component result must contain records')
        for rec in records:
            if not isinstance(rec, dict):
                raise ValueError('record must be an object')
            source = rec.get('source')
            rid = rec.get('id')
            if not isinstance(source, str) or not isinstance(rid, str):
                raise ValueError('record must have string source and id')
            key = (source, rid)
            if key in merged and merged[key] != rec:
                raise ValueError('conflicting record for %s:%s' % (source, rid))
            merged[key] = rec
    return list(merged.values())

