from _shared import CATEGORY_RANK, merge_component_records  # noqa: E402


def transform(payloads, contract):
    merged = merge_component_records(payloads)
    threshold = contract['threshold']
    if contract['only_if_blocking']:
        blocking = any(
            'blocking' in rec['tags'] and rec['score'] >= threshold for rec in merged
        )
        if not blocking:
            merged = []

    nodes = []
    for rec in merged:
        node_id = '%s:%s' % (rec['source'], rec['id'])
        nodes.append({
            'node_id': node_id,
            'duration': 1 + rec['score'] // 5,
            'category': rec['category'],
        })

    nodes.sort(key=lambda n: (CATEGORY_RANK[n['category']], n['node_id']))
    node_ids = [n['node_id'] for n in nodes]

    predecessors = {}
    for node in nodes:
        predecessors[node['node_id']] = [
            other['node_id']
            for other in nodes
            if CATEGORY_RANK[other['category']] < CATEGORY_RANK[node['category']]
        ]

    finish = {}
    path = {}
    for node in nodes:
        preds = predecessors[node['node_id']]
        if not preds:
            finish[node['node_id']] = node['duration']
            path[node['node_id']] = [node['node_id']]
        else:
            max_f = max(finish[p] for p in preds)
            best_pred = min(
                [p for p in preds if finish[p] == max_f],
                key=lambda p: path[p],
            )
            finish[node['node_id']] = node['duration'] + max_f
            path[node['node_id']] = path[best_pred] + [node['node_id']]

    waves = []
    scheduled = set()
    while len(scheduled) < len(node_ids):
        ready = [
            nid for nid in node_ids
            if nid not in scheduled and all(p in scheduled for p in predecessors[nid])
        ]
        ready.sort()
        waves.append(ready)
        scheduled.update(ready)

    if node_ids:
        max_f = max(finish.values())
        terminal = min(
            [nid for nid in node_ids if finish[nid] == max_f],
            key=lambda nid: path[nid],
        )
        critical_path = path[terminal]
        makespan = finish[terminal]
    else:
        critical_path = []
        makespan = 0

    records_out = sorted(merged, key=lambda r: (r['source'], r['id']))
    earliest_finish = {nid: finish[nid] for nid in sorted(node_ids)}

    return {
        'name': contract['name'],
        'result': {
            'records': records_out,
            'blocked': False,
            'waves': waves,
            'critical_path': critical_path,
            'makespan': makespan,
            'earliest_finish': earliest_finish,
        },
    }

